  //神许褚
  zhengqing: {
    audio: 2,
    trigger: { global: "roundEnd" },
    forced: true,
    filter() {
      return game.hasPlayer((current) => {
        return current.countMark("zhengqing");
      }) || lib.skill.zhengqing.getMostInfoLastRound()[0] > 0;
    },
    getMostInfoLastRound() {
      let max = -1;
      let players = [];
      const history = game.getAllGlobalHistory();
      if (history.length <= 1) {
        return [max, players];
      }
      for (let i = history.length - 1; i >= 0; i--) {
        const evts = history[i]["everything"].filter((evt) => {
          if (evt.name !== "damage") {
            return false;
          }
          const source = evt.source;
          return source && source.isIn();
        });
        if (evts.length) {
          let curMax = -1;
          let curPlayers = [];
          const map = {};
          for (const evt of evts) {
            const source = evt.source;
            const id = source.playerid;
            if (typeof map[id] !== "number") {
              map[id] = 0;
            }
            map[id] += evt.num;
            if (map[id] > curMax) {
              curMax = map[id];
              curPlayers = [source];
            } else if (map[id] === curMax) {
              curPlayers.add(source);
            }
          }
          if (curMax > max) {
            max = curMax;
            players = curPlayers.slice();
          } else if (curMax === max) {
            players.addArray(curPlayers);
          }
        }
        if (history[i].isRound) {
          break;
        }
      }
      return [max, players];
    },
    async content(event, trigger, player2) {
      game.countPlayer((current) => {
        if (current.hasMark("zhengqing")) {
          current.clearMark("zhengqing");
        }
      });
      const [num, players] = lib.skill.zhengqing.getMostInfoLastRound();
      let target;
      if (!players.length) {
        return;
      } else if (players.length === 1) {
        target = players[0];
      } else if (players.includes(player2)) {
        target = player2;
      } else {
        target = players.randomGet();
      }
      player2.line(target, "thunder");
      target.addMark("zhengqing", num);
      if (target === player2) {
        player2.draw(Math.min(5, num));
      } else {
        await game.asyncDraw([player2, target].sortBySeat(trigger.player));
      }
    },
    marktext: "擎",
    intro: {
      name: "争擎",
      name2: "擎",
      content: "mark"
    }
  },
