      const list = [`${hps[0] > 0 ? `摸${get.cnNumber(hps[0])}张牌，` : ""}此阶段使用的下一张【杀】无距离限制且不能被响应。`, `${hps[1] > 0 ? `摸${get.cnNumber(hps[1])}张牌，` : ""}此阶段下一次造成伤害后，回复等量体力。`];
      const result = await player2.chooseControlList({ list }).set("ai", () => {
        const player3 = get.event().player;
        let damaged = player3.getDamagedHp();
        if (damaged) {
          damaged += 0.6 * (player3.countCards("hs", (card) => {
            if (card.name === "sha" || !get.tag(card, "damage")) {
              return 0;
            }
            const info2 = get.info(card);
            if (!info2 || info2.type !== "trick") {
              return false;
            }
            if (info2.notarget) {
              return false;
            }
            if (info2.selectTarget !== void 0) {
              if (Array.isArray(info2.selectTarget)) {
                if (info2.selectTarget[1] === -2) {
                  return 1;
                }
                if (info2.selectTarget[1] === -1) {
                  let func = info2.filterTarget;
                  if (typeof func !== "function") {
                    func = () => true;
                  }
                  return game.countPlayer((cur) => {
                    return func(card, player3, cur);
                  });
                }
                return Math.max(1, info2.selectTarget[0], info2.selectTarget[1]);
              } else {
                if (info2.selectTarget === -2) {
                  return 1;
                }
                if (info2.selectTarget === -1) {
                  let func = info2.filterTarget;
                  if (typeof func !== "function") {
                    func = () => true;
                  }
                  return game.countPlayer((cur) => {
                    return func(card, player3, cur);
                  });
                }
                return Math.max(1, info2.selectTarget);
              }
            }
            return 1;
          }) + Math.max(player3.getCardUsable("sha"), player3.countCards("hs", "sha")));
        }
        if (damaged > player3.hp) {
          return "选项二";
        }
        return "选项一";
      }).forResult();
      event.result = {
        bool: result.control !== "cancel2",
        cost_data: result.control
      };
