  dczhidui: {
    audio: 2,
    init(player2) {
      player2.addSkill("dczhidui_mark");
    },
    onremove(player2) {
      player2.removeSkill("dczhidui_mark");
    },
    trigger: { player: "useCard" },
    filter(event, player2) {
      const history = game.getAllGlobalHistory("useCard");
      const index = history.indexOf(event);
      return index >= 1;
    },
    async cost(event, trigger, player2) {
      const history = game.getAllGlobalHistory("useCard");
      const index = history.indexOf(trigger);
      if (index < 1) {
        return;
      }
      const bool1 = get.cardNameLength(trigger.card) === get.cardNameLength(history[index - 1].card);
      const bool2 = get.type2(trigger.card) === get.type2(history[index - 1].card);
      if (bool1 && bool2) {
        const result = await player2.chooseControl({
          prompt: get.prompt2(event.skill),
          controls: ["摸两张牌", `令${get.translation(trigger.card)}不计入次数`],
          ai() {
            const { player: player3, controls } = get.event();
            const usable = player3.getCardUsable(get.event().getTrigger().card);
            if (usable <= 0) {
              return controls[1];
            }
            return controls[0];
          }
        }).forResult();
        if (typeof result?.control === "string") {
          event.result = {
            bool: true,
            cost_data: result.control
          };
        }
      } else if (!bool1 && !bool2) {
        event.result = {
          bool: true,
          cost_data: "tempBan"
        };
      }
    },
    async content(event, trigger, player2) {
      const link = event.cost_data;
      if (link === "摸两张牌") {
        await player2.draw({ num: 2 });
      }
      if (link === `令${get.translation(trigger.card)}不计入次数`) {
        if (trigger.addCount !== false) {
          trigger.addCount = false;
          const stat = player2.getStat().card;
          const name = trigger.card.name;
          if (typeof stat[name] === "number") {
            stat[name]--;
          }
        }
      }
      if (link === "tempBan") {
        player2.tempBanSkill(event.name);
      }
    },
    locked: false,
    mod: {
      aiOrder(player2, card, num) {
        if (typeof card === "object") {
          const history = game.getAllGlobalHistory("useCard");
          if (!history.length) {
            return;
          }
          const evt = history[history.length - 1];
          if (evt?.card && get.cardNameLength(evt.card) === get.cardNameLength(card) && get.type(evt.card) === get.type2(card)) {
            return num + 114514;
          }
        }
      }
    },
    subSkill: {
      mark: {
        charlotte: true,
        init(player2, skill) {
          const history = game.getAllGlobalHistory("useCard");
          const length = history.length;
          if (!length) {
            return;
          }
          const card = history[length - 1].card;
          player2.storage[skill] = card;
          player2.markSkill(skill);
          game.broadcastAll(
            (player3, type) => {
              if (player3.marks.dczhidui_mark) {
                player3.marks.dczhidui_mark.firstChild.innerHTML = get.translation(type).slice(0, 1);
              }
            },
            player2,
            get.type2(card)
          );
        },
        onremove(player2, skill) {
          delete player2.storage[skill];
        },
        intro: {
          markcount(storage, player2) {
            return get.cardNameLength(storage);
          },
          content(storage, player2) {
            let str = "";
            str += `<li>类型：${get.translation(get.type2(storage))}`;
            str += `<br><li>牌名字数：${get.cardNameLength(storage)}`;
            return str;
          }
        },
        silent: true,
        trigger: { global: "useCard1" },
        async content(event, trigger, player2) {
          lib.skill[event.name].init(player2, event.name);
        }
      }
    }
  },
