  dcsbzhanban: {
    audio: 2,
    enable: "phaseUse",
    usable: 1,
    chooseButton: {
      dialog(event, player2) {
        const list = [1, 2, 3].map((item, index) => [index + 1, `摸${get.cnNumber(item)}张牌`]).concat([[-1, "弃置至多三张牌"]]);
        const dialog = ui.create.dialog(`斩绊：请选择是否摸牌或者弃牌`, [list.slice(0, 2), "tdnodes"], [list.slice(2, 4), "tdnodes"], "hidden");
        return dialog;
      },
      filter(button, player2) {
        if (button.link === -1) {
          return player2.countDiscardableCards(player2, "he");
        }
        return true;
      },
      check(button) {
        const player2 = get.player();
        const link = button.link;
        const hs = player2.countCards("h");
        const nums = [];
        const effs = [];
        const mine = [];
        if (link < 0) {
          const discard = player2.getCards("he").sort((a, b) => get.value(a, player2) - get.value(b, player2)).slice(0, 3);
          let num = -discard.length;
          for (const card of discard) {
            if (get.position(card) === "e") {
              num++;
            } else {
              mine.push((mine.at(-1) || 0) - get.value(card, player2));
            }
          }
          if (!num) {
            return 0;
          }
          while (num < 0) {
            nums.push(hs + num);
            num++;
          }
        } else {
          nums.push(hs + link);
          mine.push(link * get.effect(player2, { name: "draw" }, player2, player2));
        }
        for (const num of nums) {
          let eff = mine.pop();
          eff += game.filterPlayer((targetx) => targetx !== player2).reduce((sum, targetx) => {
            const numx = num - targetx.countCards("h");
            let val;
            if (numx > 0) {
              val = (numx - 3) * get.effect(targetx, { name: "draw" }, player2, player2);
            } else if (numx < 0) {
              val = (numx + 3) * get.effect(targetx, { name: "draw" }, player2, player2);
            } else {
              val = get.damageEffect(targetx, player2, player2);
            }
            if (val < 0 && player2.hasZhuSkill("dcsbtiancheng", targetx)) {
              return sum;
            }
            return sum + val;
          }, 0);
          effs.push(eff);
        }
        return Math.max(...effs);
      },
      backup(links) {
        return {
          audio: "dcsbzhanban",
          filterTarget: lib.filter.notMe,
          selectTarget: -1,
          log: false,
          link: links[0],
          async precontent(event, trigger, player2) {
            player2.logSkill("dcsbzhanban", event.result.targets);
            const link = lib.skill.dcsbzhanban_backup.link;
            if (link > 0) {
              await player2.draw(link);
            } else if (link < 0) {
              await player2.chooseToDiscard(`斩绊：请弃置一至三张牌`, "he", [1, 3], true);
            }
          },
          async content(event, trigger, player2) {
            const num = player2.countCards("h");
            const { target } = event;
            if (!target) {
              return;
            }
            const numx = num - target.countCards("h");
            if (numx > 0) {
              await target.draw(numx, "nodelay");
            } else if (numx < 0) {
              await target.chooseToDiscard(-numx, "h", true, "allowChooseAll");
            }
            if (target.hasHistory("gain", (evt) => evt.getParent(2) === event)) {
              await target.chooseToDiscard(3, "he", true);
            } else if (target.hasHistory("lose", (evt) => evt.type === "discard" && evt.getlx !== false && evt.getParent(3) === event)) {
              await target.draw(3, "nodelay");
            } else {
              await target.damage();
            }
          }
        };
      }
    },
    ai: {
      order: 5,
      result: { player: 1 }
    }
  },
