  //典韦
  dcsbkuangzhan: {
    audio: 2,
    enable: "phaseUse",
    usable: 1,
    filter(event, player2) {
      return player2.countCards("h") < player2.maxHp;
    },
    async content(event, trigger, player2) {
      await player2.drawTo(player2.maxHp);
      let num = 0;
      player2.getHistory("gain", (evt) => {
        if (evt.getParent(event.name) === event) {
          num += evt.cards.length;
        }
      });
      while (num > 0 && player2.countCards("h")) {
        num--;
        if (!game.hasPlayer((current) => player2.canCompare(current))) {
          break;
        }
        const result = await player2.chooseTarget("狂战：与一名角色拼点", true, (card, player3, target2) => {
          return target2 !== player3 && player3.canCompare(target2);
        }).set("ai", (target2) => {
          const player3 = get.player();
          if (target2.countCards("h") >= player3.countCards("h")) {
            return 0;
          }
          return get.effect(target2, { name: "sha" }, player3, player3) + 1;
        }).forResult();
        const target = result.targets[0];
        const compare = await player2.chooseToCompare(target).forResult();
        if (!player2.storage[event.name]) {
          player2.storage[event.name] = [];
          player2.when({ global: "phaseEnd" }).step(async () => {
            delete player2.storage.dcsbkuangzhan;
          });
        }
        if (compare.bool) {
          player2.storage[event.name].add(target);
          const card = { name: "sha", isCard: true };
          const targets = player2.storage[event.name].filter((current) => current !== player2 && player2.canUse(card, current, false));
          await player2.useCard(card, targets, false);
        } else {
          player2.storage[event.name].add(player2);
          const card = { name: "sha", isCard: true };
          if (target.canUse(card, player2, false)) {
            await target.useCard(card, player2, false);
          }
        }
      }
    },
    ai: {
      order: 1,
      result: {
        player(player2, target) {
          let num = player2.maxHp - player2.countCards("h");
          for (const i of game.players) {
            if (get.attitude(player2, i) <= 0) {
              num -= i.countCards("h");
            }
          }
          if (num <= 0) {
            return 1;
          }
          return 0;
        }
      }
    }
  },
  dcsbkangyong: {
    audio: 2,
    trigger: {
      player: ["phaseBegin", "phaseEnd"]
    },
    filter(event, player2, name) {
      if (name === "phaseBegin") {
        return player2.isDamaged();
      }
      return event.kangyongRecover && player2.hp > 1;
    },
    forced: true,
    async content(event, trigger, player2) {
      if (event.triggername === "phaseBegin") {
        const num = player2.maxHp - player2.hp;
        await player2.recover(num);
        trigger.kangyongRecover = num;
      } else {
        const num = Math.min(player2.hp - 1, trigger.kangyongRecover);
        if (num > 0) {
          await player2.loseHp(num);
        }
      }
    }
  },
