  dcsbhoude: {
    audio: 2,
    trigger: { target: "useCardToTargeted" },
    filter(event, player2) {
      const target = event.player;
      const phaseUse = event.getParent("phaseUse");
      if (player2 === target || !phaseUse || phaseUse.name !== "phaseUse" || phaseUse.player !== target) {
        return false;
      }
      const filterx = (evt2) => get.name(evt2.card) === "sha" && get.color(evt2.card) === "red";
      const filtery = (evt2) => get.type(evt2.card) === "trick" && get.color(evt2.card) === "black";
      if (filterx(event) && !player2.hasCards("he")) {
        return false;
      }
      if (filtery(event) && !target.hasDiscardableCards(player2, "he")) {
        return false;
      }
      const evt = event.getParent();
      const history = game.getGlobalHistory(
        "useCard",
        (evtx) => {
          const evtxx = evtx.getParent("phaseUse");
          if (player2 === evtx.player || evtxx !== phaseUse) {
            return false;
          }
          if (!evtx.targets?.includes(player2)) {
            return false;
          }
          if (filterx(event)) {
            return filterx(evtx);
          }
          if (filtery(event)) {
            return filtery(evtx);
          }
          return false;
        },
        evt
      );
      return history.indexOf(evt) === 0;
    },
    async cost(event, trigger, player2) {
      const target = trigger.player;
      let result;
      if (get.name(trigger.card) === "sha") {
        result = await player2.chooseToDiscard(get.prompt(event.skill, target), `弃置一张牌，令${get.translation(trigger.card)}对你无效。`, "chooseonly", "he").set("ai", (card) => {
          if (!get.event().goon) {
            return 0;
          }
          return 5.5 - get.value(card);
        }).set("goon", get.effect(player2, trigger.card, target, player2) < 0).forResult();
      } else {
        result = await player2.discardPlayerCard(`###${get.prompt(event.skill, target)}###<div class="text center">弃置其的一张牌，令${get.translation(trigger.card)}对你无效。</div>`, target, "he").set("chooseonly", true).set("ai", (button) => {
          if (!get.event().goon) {
            return 0;
          }
          const val = get.buttonValue(button);
          if (get.attitude(get.player(), get.owner(button.link)) > 0) {
            return -val;
          }
          return val;
        }).set("goon", get.effect(player2, trigger.card, target, player2) < 0).forResult();
      }
      if (result?.bool) {
        event.result = {
          bool: true,
          cost_data: {
            cards: result.cards,
            links: result.links
          }
        };
      }
    },
    logTarget: "player",
    async content(event, trigger, player2) {
      const target = trigger.player;
      const result = event.cost_data;
      if (result.links?.length) {
        await target.modedDiscard(result.links, player2);
      } else {
        await player2.discard(result.cards);
      }
      trigger.excluded.add(player2);
    }
  },
