  dcsilun: {
    audio: 2,
    trigger: {
      player: ["phaseZhunbeiBegin", "damageEnd"]
    },
    frequent: true,
    async content(event, trigger, player2) {
      await player2.draw(4);
      const equipCount = {};
      for (const current of game.players) {
        equipCount[current.playerid] = current.countCards("e");
      }
      for (let count = 0; count < 4; count++) {
        if (!player2.hasCards("he")) {
          break;
        }
        const cardResult = await player2.chooseCard({
          prompt: `四论：选择一张牌（${count + 1}/4）`,
          prompt2: "然后选择将此牌置于场上或牌堆的两端",
          forced: true,
          position: "he",
          ai: (card2) => {
            if (["equip", "delay"].includes(get.type(card2)) && player2.hasValueTarget(card2)) {
              return 50;
            }
            return 50 - get.value(card2);
          }
        }).forResult();
        if (!cardResult.bool) {
          break;
        }
        const card = cardResult.cards[0];
        const type = get.type(card);
        const choices = ["牌堆顶", "牌堆底"];
        if (type === "equip" && game.hasPlayer((current) => current.canEquip(card)) || type === "delay" && game.hasPlayer((current) => current.canAddJudge(card))) {
          choices.unshift("场上");
        }
        let preferredChoice = "牌堆底";
        if (["equip", "delay"].includes(type) && player2.hasValueTarget(card) && choices.includes("场上")) {
          preferredChoice = "场上";
        } else {
          const value = get.value(card);
          let nextPlayer = _status.currentPhase;
          if (nextPlayer) {
            if (trigger.name === "damage") {
              nextPlayer = nextPlayer.getNext();
            }
            if (get.attitude(player2, nextPlayer) > 0 && value >= 6 || get.attitude(player2, nextPlayer) < 0 && value <= 4.5) {
              preferredChoice = "牌堆顶";
            }
          }
        }
        const { control } = await player2.chooseControl({
          controls: choices,
          prompt: `请选择要将${get.translation(card)}置于的位置`,
          ai: () => preferredChoice
        }).forResult();
        if (control === "场上") {
          const validTargets = game.filterPlayer((current) => {
            if (type === "equip") {
              return current.canEquip(card);
            }
            if (type === "delay") {
              return current.canAddJudge(card);
            }
            return false;
          });
          const targetResult = await player2.chooseTarget({
            prompt: `将${get.translation(card)}置于一名角色的场上`,
            forced: true,
            filterTarget: (_card, _player, target) => validTargets.includes(target),
            ai: (target) => get.attitude(player2, target) * (type === "equip" ? get.value(card, target) : get.effect(
              target,
              {
                name: card.viewAs || card.name,
                cards: [card]
              },
              target,
              target
            ))
          }).forResult();
          if (targetResult.bool && targetResult.targets?.length) {
            const target = targetResult.targets[0];
            player2.line(target);
            player2.$give(card, target, false);
            if (type === "equip") {
              await target.equip(card);
            } else {
              await target.addJudge(card);
            }
          }
        } else {
          player2.$throw(card, 1e3);
          await player2.lose({
            cards: [card],
            position: ui.cardPile,
            visible: true,
            insert_card: control === "牌堆顶"
          });
          game.log(player2, "将", card, "置于了", `#y${control}`);
        }
        for (const current of game.filterPlayer()) {
          const currentEquipCount = current.countCards("e");
          const previousEquipCount = equipCount[current.playerid] || 0;
          if (currentEquipCount !== previousEquipCount) {
            await current.link(false);
            await current.turnOver(false);
          }
          equipCount[current.playerid] = currentEquipCount;
        }
      }
    }
  },
