      let num = 0;
      for (let i = 0; i < ui.cardPile.childNodes.length; i++) {
        const card = ui.cardPile.childNodes[i];
        if (get.number(card) === 7) {
          num++;
          if (num >= player2.maxHp) {
            break;
          }
        }
      }
      if (num < 1) {
        num = 1;
      }
      if (num > player2.hp) {
        await player2.recover(num - player2.hp);
      } else if (num < player2.hp) {
        await player2.loseHp(player2.hp - num);
      }
      const result = await player2.chooseToGuanxing(player2.hp).set("prompt", "尽瘁：点击或拖动将牌移动到牌堆顶或牌堆底").set("processAI", (list) => {
        const cards2 = list[0][1];
        const player3 = _status.event.player;
        let target = _status.currentPhase || player3;
        const name = _status.event.getTrigger().name;
        const countWuxie = (current) => {
          let num2 = current.getKnownCards(player3, (card) => {
            return get.name(card, current) === "wuxie";
          });
          if (num2 && current !== player3) {
            return num2;
          }
          const skills2 = current.getSkills("invisible").concat(lib.skill.global);
          game.expandSkills(skills2);
          for (let i = 0; i < skills2.length; i++) {
            const ifo = get.info(skills2[i]);
            if (!ifo) {
              continue;
            }
            if (ifo.viewAs && typeof ifo.viewAs !== "function" && ifo.viewAs.name === "wuxie") {
              if (!ifo.viewAsFilter || ifo.viewAsFilter(current)) {
                num2++;
                break;
              }
            } else {
              const hiddenCard = ifo.hiddenCard;
              if (typeof hiddenCard === "function" && hiddenCard(current, "wuxie")) {
                num2++;
                break;
              }
            }
          }
          return num2;
        };
        const top = [];
        const bottom = [];
        for (let i = 0; i < cards2.length; i++) {
          if (get.number(cards2[i]) === 7) {
            bottom.addArray(cards2.splice(i--, 1));
          }
        }
        switch (name) {
          case "phaseJieshu":
            target = target.next;
          // [falls through]
          case "phaseZhunbei": {
            const att = get.sgn(get.attitude(player3, target));
            const judges = target.getCards("j");
            let needs = 0;
            let wuxie = countWuxie(target);
            for (let i = Math.min(cards2.length, judges.length) - 1; i >= 0; i--) {
              const j = judges[i];
              if (wuxie > 0 && get.effect(target, j, target, target) < 0) {
                wuxie--;
                continue;
              }
              const judge = get.judge(j);
              cards2.sort((a, b) => {
                return (judge(b) - judge(a)) * att;
              });
              if (judge(cards2[0]) * att < 0) {
                needs++;
                continue;
              } else {
                top.unshift(cards2.shift());
              }
            }
            if (needs > 0 && needs >= judges.length) {
              bottom.addArray(cards2);
              return [top, bottom];
            }
            cards2.sort((a, b) => {
              return (get.value(b, target) - get.value(a, target)) * att;
            });
            while (needs--) {
              top.unshift(cards2.shift());
            }
            while (cards2.length) {
              if (get.value(cards2[0], target) > 6 === att > 0) {
                top.unshift(cards2.shift());
              } else {
                break;
              }
            }
            bottom.addArray(cards2);
            return [top, bottom];
          }
          default:
            cards2.sort((a, b) => {
              return get.value(b, target) - get.value(a, target);
            });
            while (cards2.length) {
              if (get.value(cards2[0], target) > 6) {
                top.unshift(cards2.shift());
              } else {
                break;
              }
            }
            bottom.addArray(cards2);
            return [top, bottom];
        }
      }).forResult();
      if (!result.bool || !result.moved[0].length) {
        player2.addTempSkill("guanxing_fail");
      }
