  dccaizhuang: {
    audio: 2,
    enable: "phaseUse",
    usable: 1,
    filter(event, player2) {
      return player2.hasCard((card) => {
        return lib.filter.cardDiscardable(card, player2, "dccaizhuang");
      }, "he");
    },
    complexCard: true,
    selectCard: [1, Infinity],
    position: "he",
    filterCard: lib.filter.cardDiscardable,
    check(card) {
      const cache = lib.skill.dccaizhuang.tempCache();
      if (!cache || cache.no) {
        return 0;
      }
      _status.event.player;
      const suit = get.suit(card);
      if (ui.selected.cards.filter((i) => {
        return get.suit(i) === suit;
      }).length < (cache[suit] || 0)) {
        if (get.position(card) === "h") {
          return 15 - get.value(card);
        }
        return 9 - get.value(card);
      }
      return 0;
    },
    tempCache() {
      let cache = _status.event.getTempCache("dccaizhuang", "dsuits");
      if (cache) {
        return cache;
      }
      cache = { no: true };
      _status.event.putTempCache("dccaizhuang", "dsuits", cache);
      const player2 = _status.event.player;
      const suits = {};
      lib.suit.forEach((i) => {
        suits[i] = 0;
      });
      player2.getCards("h", (i) => {
        const suit = get.suit(i);
        if (lib.suit.includes(suit)) {
          suits[suit]++;
        }
      });
      const sortedSuits = Object.fromEntries(Object.entries(suits).sort((a, b) => b[1] - a[1]));
      let dis = 0;
      let idx = 0;
      let dsuits = 0;
      let leave = 0;
      for (const i in sortedSuits) {
        idx++;
        if (!sortedSuits[i]) {
          continue;
        }
        let num = 1;
        if (idx > 2 || sortedSuits[i] < 3) {
          num = sortedSuits[i];
        }
        cache[i] = num;
        dis += num;
        suits[i] -= num;
        dsuits++;
      }
      for (const i in suits) {
        if (suits[i]) {
          leave++;
        }
      }
      player2.getCards("e", (i) => {
        const suit = get.suit(i);
        if (!cache[suit]) {
          dsuits++;
          cache[suit] = 1;
          dis++;
        }
      });
      let draw = 0;
      const e = [0, 1, 4 / 3, 2, 4];
      if (dsuits <= leave) {
        return false;
      }
      do {
        draw += e[dsuits--];
      } while (dsuits > leave);
      if (draw > dis) {
        delete cache.no;
        _status.event.putTempCache("dccaizhuang", "dsuits", cache);
        return cache;
      }
      return false;
    },
    async content(event, trigger, player2) {
      const num = event.cards.map((card) => get.suit(card, player2)).toUniqued().length;
      while (true) {
        await player2.draw();
        if (player2.getCards("h").map((card) => get.suit(card, player2)).toUniqued().length >= num) {
          break;
        }
      }
    },
    ai: {
      order: 2,
      result: { player: 1 }
    }
  },
