    async content(event, trigger, player2) {
      player2.changeZhuanhuanji("dcshoutan");
      player2.addTempSkill("dcshoutan_blocker", {
        player: ["useCard1", "useSkillBegin", "phaseUseEnd"]
      });
    },
    zhuanhuanji: true,
    mark: true,
