  dcgeyuan: {
    audio: 2,
    trigger: {
      global: ["loseAfter", "loseAsyncAfter", "cardsDiscardAfter", "equipAfter"]
    },
    forced: true,
    filter(event, player2) {
      const cards2 = event.getd();
      return cards2.some((card) => lib.skill.dcgeyuan.filterNumber(player2, get.number(card, false)));
    },
    async content(event, trigger, player2) {
      const discardedCards = trigger.getd();
      let completed = false;
      while (discardedCards.length) {
        const card = discardedCards.find((card2) => lib.skill.dcgeyuan.filterNumber(player2, get.number(card2, false)));
        if (!card) {
          break;
        }
        discardedCards.remove(card);
        const number = get.number(card, false);
        game.log(player2, "将", `#y${get.strNumber(number)}`, "记录为", "#g“圆环之弧”");
        player2.markAuto("dcgeyuan_homura", [number]);
        player2.markSkill("dcgeyuan");
        if (player2.getStorage("dcgeyuan").length <= player2.getStorage("dcgeyuan_homura").length) {
          completed = true;
          break;
        }
      }
      if (!completed) {
        return;
      }
      if (player2.storage.dcgusuan) {
        const result = await player2.chooseTarget({
          prompt: "割圆：你可以选择至多三名角色",
          prompt2: "第一名角色摸三张牌，第二名角色弃置四张牌，第三名角色将所有手牌与牌堆底的牌交换",
          selectTarget: [1, 3]
        }).forResult();
        if (result.bool) {
          const targets = result.targets;
          player2.line(targets);
          await targets[0].draw(3);
          if (targets[1]?.hasCards("he")) {
            await targets[1].chooseToDiscard({
              position: "he",
              forced: true,
              selectCard: 4
            });
          }
          if (targets[2]) {
            const target = targets[2];
            const cards2 = get.bottomCards(5);
            await game.cardsGotoOrdering(cards2);
            const handCards = target.getCards("h");
            if (handCards.length) {
              await target.lose({
                cards: handCards,
                position: ui.cardPile
              });
            }
            await target.gain({ cards: cards2, animate: "draw" });
          }
        }
      } else {
        const arc2 = player2.getStorage("dcgeyuan_homura");
        const firstNumber2 = arc2[0];
        const lastNumber2 = arc2[arc2.length - 1];
        const cards2 = [];
        const loseList = [];
        for (const current of game.filterPlayer()) {
          const currentCards = current.getCards("ej", (card) => {
            const number = get.number(card);
            return number === firstNumber2 || number === lastNumber2;
          });
          if (!currentCards.length) {
            continue;
          }
          current.$throw(currentCards);
          loseList.push([current, currentCards]);
          cards2.addArray(currentCards);
        }
        if (loseList.length) {
          await game.loseAsync({ lose_list: loseList }).setContent("chooseToCompareLose");
        }
        for (const card of ui.cardPile.childNodes) {
          const number = get.number(card, false);
          if (number === firstNumber2 || number === lastNumber2) {
            cards2.push(card);
          }
        }
        if (cards2.length) {
          if (loseList.length) {
            await game.delayx();
          }
          await player2.gain({ cards: cards2, animate: "gain2" });
        }
      }
      const arc = player2.getStorage("dcgeyuan_homura");
      const firstNumber = arc[0];
      const lastNumber = arc[arc.length - 1];
      player2.storage.dcgeyuan_homura = [];
      game.log(player2, "清空了", "#g“圆环之弧”");
      player2.markSkill("dcgeyuan");
      if (player2.getStorage("dcgeyuan").length > 3) {
        player2.unmarkAuto("dcgeyuan", [firstNumber, lastNumber]);
        game.log(player2, "从", "#g“圆环之理”", "中移除了", `#y${get.strNumber(firstNumber)}`, "和", `#y${get.strNumber(lastNumber)}`);
      }
    },
    group: "dcgeyuan_kyubey",
    filterNumber(player2, num) {
      const list1 = player2.getStorage("dcgeyuan");
      const list2 = player2.getStorage("dcgeyuan_homura");
      if (!list1.includes(num)) {
        return false;
      }
      if (!list2.length) {
        return true;
      }
      if (list2.includes(num)) {
        return false;
      }
      const madoka = list1.indexOf(num);
      for (const number of list2) {
        const homura = list1.indexOf(number);
        const distance = Math.abs(madoka - homura);
        if (distance === 1 || distance === list1.length - 1) {
          return true;
        }
      }
      return false;
    },
    subSkill: {
      kyubey: {
        audio: "dcgeyuan",
        trigger: {
          global: "phaseBefore",
          player: "enterGame"
        },
        forced: true,
        filter(event, player2) {
          return (event.name !== "phase" || game.phaseNumber === 0) && !player2.storage.dcgusuan;
        },
        async content(event, trigger, player2) {
          const list = [];
          for (let number = 1; number <= 13; number++) {
            list.push(number);
          }
          list.randomSort();
          player2.storage.dcgeyuan = list;
          player2.markSkill("dcgeyuan");
          const str = `#y${list.map((number) => get.strNumber(number)).join(",")}`;
          game.log(player2, "将", "#y“圆环之理”", "赋值为", str);
        }
      }
    },
    intro: {
      name: "圆环之理",
      markcount(storage, player2) {
        if (!player2.storage.dcgeyuan || !player2.getStorage("dcgeyuan_homura").length) {
          return 0;
        }
        let list = player2.storage.dcgeyuan.filter((number) => lib.skill.dcgeyuan.filterNumber(player2, number));
        if (!list.length) {
          return 0;
        }
        list = list.map((number) => number === 10 ? "X" : get.strNumber(number));
        return list.join("");
      },
      mark(dialog, storage, player2) {
        dialog.content.style["overflow-x"] = "visible";
        if (!storage || !storage.length) {
          return "（圆环之理尚不存在）";
        }
        const list = storage;
        const list2 = player2.getStorage("dcgeyuan_homura");
        const core2 = document.createElement("div");
        core2.style.width = "0";
        const centerX = -15;
        const centerY = 80;
        const radius = 80;
        const radian = Math.PI * 2 / list.length;
        const fullList = ["Ａ", "２", "３", "４", "５", "６", "７", "８", "９", "10", "Ｊ", "Ｑ", "Ｋ"];
        for (const [index, number] of list.entries()) {
          const td = document.createElement("div");
          let color = "";
          if (list2[0] === number) {
            color = ' class="yellowtext"';
          } else if (list2.includes(number)) {
            color = ' class="greentext"';
          }
          td.innerHTML = `<span${color}>[${fullList[number - 1]}]</span>`;
          td.style.position = "absolute";
          core2.appendChild(td);
          td.style.left = `${centerX + radius * Math.sin(radian * index)}px`;
          td.style.top = `${centerY - radius * Math.cos(radian * index)}px`;
        }
        dialog.content.appendChild(core2);
      }
    }
  },
