  dcsushou: {
    audio: 2,
    trigger: { global: "phaseUseBegin" },
    filter(event, player2) {
      return player2.hp > 0 && event.player.isMaxHandcard(true);
    },
    logTarget: "player",
    check(event, player2) {
      let num = player2.hp;
      if (player2.hasSkill("dczhongjie") && (player2.storage.dczhongjie_roundcount || 0) < game.roundNumber) {
        num++;
      }
      return num > 1;
    },
    async content(event, trigger, player2) {
      await player2.loseHp();
      if (player2.isDead() || !player2.isIn()) {
        return;
      }
      const target = trigger.player;
      const num = player2.getDamagedHp();
      if (num > 0) {
        await player2.draw(num);
      }
      if (player2 === target) {
        return;
      }
      let targetCards = target.getCards("h");
      if (targetCards.length < 2) {
        return;
      }
      const handCards = player2.getCards("h");
      targetCards = targetCards.randomGets(Math.floor(targetCards.length / 2));
      if (!handCards.length) {
        await player2.viewCards(`${get.translation(target)}的部分手牌`, targetCards);
        return;
      }
      const max = Math.min(handCards.length, targetCards.length, player2.getDamagedHp());
      const result = await player2.chooseToMove({
        prompt: `夙守：交换至多${get.cnNumber(max)}张牌`,
        list: [
          [`${get.translation(target)}的部分手牌`, targetCards, "dcsushou_tag"],
          ["你的手牌", handCards]
        ],
        processAI: (list) => {
          const { max: max2, target: target2 } = get.event();
          const player3 = get.player();
          const att = get.attitude(player3, target2);
          if (max2 <= 0) {
            return [list[0][1], list[1][1]];
          }
          let gain;
          let give;
          if (att <= 1) {
            gain = list[0][1].sort((a, b) => player3.getUseValue(b, null, true) - player3.getUseValue(a, null, true)).slice(0, max2);
            give = list[1][1].sort((a, b) => get.value(a, player3) - get.value(b, player3)).slice(0, max2);
          } else {
            give = list[1][1].sort((a, b) => target2.getUseValue(b, null, true) - target2.getUseValue(a, null, true)).slice(0, max2);
            gain = list[0][1].sort((a, b) => get.value(a, target2) - get.value(b, target2)).slice(0, max2);
          }
          for (const card of gain) {
            if (att <= 1 && get.value(card, player3) < get.value(give[0], player3)) {
              continue;
            }
            const replacement = give.shift();
            list[0][1].remove(card);
            list[0][1].push(replacement);
            list[1][1].remove(replacement);
            list[1][1].push(card);
            if (!give.length) {
              break;
            }
          }
          return [list[0][1], list[1][1]];
        }
      }).set("filterMove", (from, to, moved) => {
        if (typeof to === "number") {
          return false;
        }
        const player3 = _status.event.player;
        const handCards2 = player3.getCards("h");
        const changed = handCards2.filter((card) => !moved[1].includes(card));
        const changed2 = moved[1].filter((card) => !handCards2.includes(card));
        if (changed.length < player3.getDamagedHp()) {
          return true;
        }
        const pos1 = moved[0].includes(from.link) ? 0 : 1;
        const pos2 = moved[0].includes(to.link) ? 0 : 1;
        if (pos1 === pos2) {
          return true;
        }
        if (pos1 !== 0) {
          if (changed2.includes(from.link)) {
            return true;
          }
          return changed.includes(to.link);
        }
        if (changed.includes(from.link)) {
          return true;
        }
        return changed2.includes(to.link);
      }).set("max", max).set("target", target).forResult();
      const currentHandCards = player2.getCards("h");
      const currentTargetCards = target.getCards("h");
      const cards1 = [];
      const cards2 = [];
      for (const card of result.moved[0]) {
        if (!currentTargetCards.includes(card)) {
          cards1.push(card);
        }
      }
      for (const card of result.moved[1]) {
        if (!currentHandCards.includes(card)) {
          cards2.push(card);
        }
      }
      if (cards1.length) {
        await player2.swapHandcards(target, cards1, cards2);
      }
    }
  },
  //蓝曹华
