          const history = event.player.actionHistory;
          if (history[history.length - 1].isRound) {
            return true;
          }
          for (let i = history.length - 2; i >= 0; i--) {
            if (history[i].isMe) {
              return false;
            }
            if (history[i].isRound) {
              return true;
            }
          }
