  pytianjiang_move: {
    audio: "pytianjiang",
    prompt: "将装备区里的一张牌移动至其他角色的装备区",
    enable: "phaseUse",
    position: "e",
    sourceSkill: "pytianjiang",
    filter(event, player2) {
      return player2.hasCards("e");
    },
    check() {
      return 1;
    },
    filterCard: true,
    filterTarget(event, player2, target) {
      return target !== player2 && target.canEquip(ui.selected.cards[0], true);
    },
    prepare: "give",
    discard: false,
    lose: false,
    async content(event, trigger, player2) {
      const { cards: cards2, target } = event;
      await target.equip(cards2[0]);
      if (cards2[0].name.indexOf("pyzhuren_") === 0 && !player2.getCards("e").includes(cards2[0])) {
        await player2.draw(2);
      }
    },
    ai: {
      order: (item, player2) => {
        if (player2.hasCard((i) => get.subtype(i) === "equip1", "h")) {
          return 11;
        }
        return 1;
      },
      expose: 0.2,
      result: {
        target(player2, target) {
          if (ui.selected.cards.length) {
            const card = ui.selected.cards[0];
            const tv = get.value(card, target);
            const sub = get.subtype(card);
            if (sub === "equip1") {
              let ev = Infinity;
              const te = target.getEquips(1);
              if (!te.length) {
                return tv;
              }
              for (const equip of te) {
                ev = Math.min(ev, get.value(equip));
              }
              if (card.name.indexOf("pyzhuren_") === 0) {
                return 2 + tv - ev;
              }
              return tv - ev;
            }
            if (target.hasCard((i) => get.subtype(i) === sub, "he")) {
              return 0;
            }
            const pv = get.value(card, player2);
            if (pv > 0 && Math.abs(tv) <= pv) {
              return 0;
            }
            return tv;
          }
          return 0;
        }
      }
    }
  },
